import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";var i=JSON.parse(`{"title":"简介","description":"","frontmatter":{},"headers":[],"relativePath":"middleware/docker/basic/index.md","filePath":"middleware/docker/basic/index.md"}`),a={name:`middleware/docker/basic/index.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to “简介”">​</a></h1><ul><li>Docker 是一种容器化技术，它能将应用程序及其依赖打包成标准化的 “容器”，确保应用在任何环境下都能以相同方式运行，核心解决 “环境一致性” 和 “部署效率” 问题。</li></ul><h2 id="资源" tabindex="-1">资源 <a class="header-anchor" href="#资源" aria-label="Permalink to “资源”">​</a></h2><ul><li>官网地址：<a href="https://docker.com" target="_blank" rel="noreferrer">https://docker.com</a></li><li>文档地址：<a href="https://docs.docker.com" target="_blank" rel="noreferrer">https://docs.docker.com</a></li><li>仓库地址：<a href="https://hub.docker.com" target="_blank" rel="noreferrer">https://hub.docker.com</a></li></ul><h2 id="优点" tabindex="-1">优点 <a class="header-anchor" href="#优点" aria-label="Permalink to “优点”">​</a></h2><h3 id="轻量级-资源占用低" tabindex="-1">轻量级，资源占用低 <a class="header-anchor" href="#轻量级-资源占用低" aria-label="Permalink to “轻量级，资源占用低”">​</a></h3><ul><li>容器共享宿主机的操作系统内核，无需像虚拟机那样单独加载完整操作系统，启动时间从虚拟机的 “分钟级” 缩短到 “秒级”，内存和磁盘占用仅为虚拟机的几分之一。</li></ul><h3 id="环境一致性-消除-本地能跑线上崩" tabindex="-1">环境一致性，消除 “本地能跑线上崩” <a class="header-anchor" href="#环境一致性-消除-本地能跑线上崩" aria-label="Permalink to “环境一致性，消除 “本地能跑线上崩””">​</a></h3><ul><li>开发时将应用和依赖打包成镜像，测试、生产环境直接使用相同镜像启动容器，完全避免因环境配置差异导致的运行问题。</li></ul><h3 id="快速部署与扩展" tabindex="-1">快速部署与扩展 <a class="header-anchor" href="#快速部署与扩展" aria-label="Permalink to “快速部署与扩展”">​</a></h3><ul><li>基于镜像创建容器仅需几秒，配合 Kubernetes 等工具可实现容器的自动化创建、销毁和扩容，大幅提升部署效率。</li></ul><h3 id="隔离性强-安全可控" tabindex="-1">隔离性强，安全可控 <a class="header-anchor" href="#隔离性强-安全可控" aria-label="Permalink to “隔离性强，安全可控”">​</a></h3><ul><li>每个容器拥有独立的文件系统、网络和进程空间，容器间相互隔离，一个容器故障不会影响其他容器运行。</li></ul>`,13)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};